import java.util.Scanner;

public class Main {
    static long[] sequence_vals = new long[18];
    static int min_moves_result = 0;

    static void dfs(int current_moves, long remaining, int position) {
        if (current_moves > min_moves_result)
            return;
        if (remaining == 0) {
            min_moves_result = Math.min(min_moves_result, current_moves);
            return;
        }
        int needed = (int) (remaining / sequence_vals[position]);
        // First recursive call
        dfs(current_moves + position * needed++, remaining - needed * sequence_vals[position], position - 1);
        // Second recursive call
        dfs(current_moves + needed * position, needed * sequence_vals[position] - remaining, position - 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long val_input = scanner.nextLong();

        sequence_vals[1] = 1;
        for (int i = 2; i < 18; i++) {
            sequence_vals[i] = sequence_vals[i - 1] * 10 + 1;
        }

        long temp_val = val_input;
        min_moves_result = 0;

        while (temp_val > 0) {
            for (int i = 1; i < 18; i++) {
                if (sequence_vals[i] > temp_val) {
                    min_moves_result += (i - 1);
                    temp_val -= sequence_vals[i - 1];
                    break;
                }
            }
        }

        dfs(0, val_input, 16);
        System.out.println(min_moves_result);
        scanner.close();
    }
}
